<?php
if (!defined('ABSPATH')) { exit; }
function csktm_public_route(){if(is_admin()||defined('REST_REQUEST')&&REST_REQUEST)return null;$path=wp_parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);$homePath=wp_parse_url(home_url('/'),PHP_URL_PATH);if($homePath&&$homePath!=='/'&&str_starts_with($path,untrailingslashit($homePath).'/'))$path=substr($path,strlen(untrailingslashit($homePath)));$routes=get_option('cskt_migration_routes',array());return $routes[csktm_route_key($path?:'/')]??null;}
// WordPress applies this filter before rest_api_loaded defines REST_REQUEST.
// Keep its native REST query intact even when the reviewed home route is '/'.
add_filter('request',function($query){if(array_key_exists('rest_route',$query))return $query;$route=csktm_public_route();if($route&&$route['type']==='content'){$id=(int)$route['postId'];$type=get_post_type($id);if($type==='page')return array('page_id'=>$id);if($type)return array('p'=>$id,'post_type'=>$type);}return $query;},1);
add_filter('redirect_canonical',function($redirect){return csktm_public_route()?false:$redirect;},10,1);
add_action('template_redirect',function(){
    $route=csktm_public_route();if(!$route)return;
    if($route['type']==='redirect'){
        if($route['status']===410){status_header(410);nocache_headers();header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Content withdrawn</title><main><h1>Content withdrawn</h1><p>This resource has been removed from the published collection.</p><p><a href="'.esc_url(home_url('/')).'">Go to the site home page</a></p></main></html>';exit;}
        wp_safe_redirect(home_url($route['targetPath']),301,'CSKT reviewed migration');exit;
    }
    if($route['type']==='asset'){wp_safe_redirect($route['targetUrl'],302,'CSKT retained media');exit;}
    if($route['type']==='content'){$path=wp_parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);$canonical=wp_parse_url(home_url($route['path']),PHP_URL_PATH);if($path!==$canonical){wp_safe_redirect(home_url($route['path']),301,'CSKT reviewed route');exit;}}
},0);
function csktm_permalink($link,$id){$id=is_object($id)?$id->ID:$id;$route=get_post_meta($id,'_cskt_route',true);return is_string($route)&&$route!==''?home_url($route):$link;}
add_filter('page_link','csktm_permalink',10,2);add_filter('post_link','csktm_permalink',10,2);add_filter('post_type_link','csktm_permalink',10,2);
function csktm_meta_json($id,$key){$raw=get_post_meta($id,$key,true);return is_string($raw)&&$raw!==''?json_decode($raw,true):null;}
function csktm_gis_html($items){$out='';foreach($items?:array()as$g){$url=esc_url($g['url']);$out.='<section class="cskt-gis" aria-label="'.esc_attr($g['title']).'"><h2>'.esc_html($g['title']).'</h2>';if(!empty($g['description']))$out.='<p>'.esc_html($g['description']).'</p>';$out.='<iframe src="'.$url.'" title="'.esc_attr($g['title']).'" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p><a href="'.$url.'" target="_blank" rel="noopener">Open the interactive map in a new tab</a></p><div class="cskt-map-description"><h3>Map description</h3>'.wp_kses_post($g['fallbackHtml']).'</div></section>';}return $out;}
add_filter('the_content',function($content){
    if(!is_singular()||!in_the_loop()||!is_main_query())return $content;$id=get_the_ID();$extra='';$archive=get_post_meta($id,'_cskt_archive',true);
    if($archive==='1')$content='<aside class="cskt-archive" aria-label="Archived content"><strong>Archived</strong><p>This historical resource is retained for reference.</p></aside>'.$content;
    $d=csktm_meta_json($id,'_cskt_document');if(is_array($d)&&!empty($d['nativeUrl'])){$extra.='<section class="cskt-document"><h2>Document</h2><dl><dt>Version</dt><dd>'.esc_html($d['versionLabel']).'</dd><dt>Format</dt><dd>'.esc_html($d['mimeType']).'</dd><dt>Size</dt><dd>'.esc_html(size_format((int)$d['bytes'],1)).'</dd></dl>';$description=is_string($d['description']??null)?trim($d['description']):'';$alt=is_string($d['altText']??null)?trim($d['altText']):'';if($description!=='')$extra.='<p>'.esc_html($description).'</p>';if(str_starts_with(strtolower((string)($d['mimeType']??'')),'image/')&&$alt!==''&&$alt!==$description)$extra.='<p class="cskt-document-image-description">'.esc_html($alt).'</p>';$extra.='<p><a href="'.esc_url($d['nativeUrl']).'" download="'.esc_attr($d['downloadName']).'">Download '.esc_html($d['downloadName']).'</a></p></section>';}
    $n=csktm_meta_json($id,'_cskt_notice');if(is_array($n)){$extra.='<section class="cskt-notice"><h2>Notice details</h2><dl><dt>Type</dt><dd>'.esc_html(ucfirst($n['type']??'general')).'</dd>';foreach(array('startsAt'=>'Starts','endsAt'=>'Ends')as$key=>$label)if(!empty($n[$key]))$extra.='<dt>'.$label.'</dt><dd><time datetime="'.esc_attr($n[$key]).'">'.esc_html(wp_date('F j, Y, g:i a T',strtotime($n[$key]))).'</time></dd>';if(!empty($n['location']))$extra.='<dt>Location</dt><dd>'.esc_html($n['location']).'</dd>';$extra.='</dl></section>';}
    return '<div class="cskt-published-content">'.$content.$extra.csktm_gis_html(csktm_meta_json($id,'_cskt_gis')).'</div>';
},20);
add_action('wp_enqueue_scripts',function(){wp_register_style('cskt-reviewed-content',false,array(),CSKTM_VERSION);wp_enqueue_style('cskt-reviewed-content');wp_add_inline_style('cskt-reviewed-content','.cskt-published-content{overflow-wrap:anywhere}.cskt-published-content img,.cskt-published-content video{max-width:100%;height:auto}.cskt-published-content table{max-width:100%;display:block;overflow:auto}.cskt-published-content iframe{width:100%;min-height:32rem;border:1px solid #b8b8b8;background:#fff}.cskt-document,.cskt-gis,.cskt-notice,.cskt-archive{padding:1.2rem 0;border-top:1px solid #b8b8b8;margin-top:1.5rem}.cskt-document dl,.cskt-notice dl{display:grid;grid-template-columns:minmax(6rem,1fr) 3fr;gap:.5rem 1rem}.cskt-document dd,.cskt-notice dd{margin:0}.cskt-directory{list-style:none;padding:0}.cskt-directory li{padding:1rem 0;border-bottom:1px solid #ccc}.cskt-directory small{display:block}.cskt-map-description{margin:1rem 0}@media(max-width:600px){.cskt-published-content iframe{min-height:24rem}.cskt-document dl,.cskt-notice dl{display:block}.cskt-document dd,.cskt-notice dd{margin:0 0 .75rem}}');});
function csktm_directory($attrs,$type){$attrs=shortcode_atts(array('topic'=>'','per_page'=>20),$attrs);$paged=max(1,(int)get_query_var('paged'),(int)get_query_var('page'));$args=array('post_type'=>$type,'post_status'=>'publish','posts_per_page'=>min(100,max(1,(int)$attrs['per_page'])),'paged'=>$paged);if($attrs['topic']!=='')$args['tax_query']=array(array('taxonomy'=>'cskt_topic','field'=>'name','terms'=>$attrs['topic']));$q=new WP_Query($args);$out='<ul class="cskt-directory">';foreach($q->posts as$p){$out.='<li><a href="'.esc_url(get_permalink($p->ID)).'">'.esc_html($p->post_title).'</a>';if($p->post_excerpt)$out.='<p>'.esc_html($p->post_excerpt).'</p>';$d=csktm_meta_json($p->ID,'_cskt_document');if($d)$out.='<small>'.esc_html($d['versionLabel']).' · '.esc_html($d['mimeType']).'</small>';if(get_post_meta($p->ID,'_cskt_archive',true)==='1')$out.='<small>Archived</small>';$out.='</li>';}$out.='</ul>';if(!$q->found_posts)$out.='<p>No published resources match this collection.</p>';if($q->max_num_pages>1)$out.='<nav aria-label="Collection pages">'.paginate_links(array('current'=>$paged,'total'=>$q->max_num_pages,'type'=>'list')).'</nav>';return $out;}
add_shortcode('cskt_documents',function($a){return csktm_directory($a,'cskt_document');});add_shortcode('cskt_projects',function($a){return csktm_directory($a,'cskt_project');});add_shortcode('cskt_notices',function($a){return csktm_directory($a,'cskt_notice');});add_shortcode('cskt_news',function($a){return csktm_directory($a,'post');});
add_action('init',function(){if(!function_exists('register_block_pattern'))return;foreach(array('documents'=>'Document library','projects'=>'Project directory','notices'=>'Notice board','news'=>'News')as$key=>$title)register_block_pattern('cskt/'.$key,array('title'=>$title,'description'=>'Native published '.$title.' with topics and pagination.','categories'=>array('text'),'content'=>'<!-- wp:heading --><h2>'.$title.'</h2><!-- /wp:heading --><!-- wp:shortcode -->[cskt_'.$key.']<!-- /wp:shortcode -->'));});
add_action('admin_menu',function(){add_management_page('Reviewed migrations','Reviewed migrations','manage_options','cskt-migrations',function(){if(!csktm_allowed())return;echo '<div class="wrap"><h1>Reviewed migrations</h1><p>Inspect, preview and apply the exact reviewed release through the migration workspace. Native pages, documents, projects and notices remain editable through WordPress.</p><table class="widefat"><thead><tr><th>Release</th><th>Status</th><th>Created</th><th>Retained result</th></tr></thead><tbody>';foreach(array_reverse(get_option('cskt_migration_releases',array()))as$r)echo '<tr><td>'.esc_html($r['id']).'</td><td>'.esc_html($r['status']).'</td><td>'.esc_html($r['createdAt']).'</td><td><a href="'.esc_url(rest_url(CSKTM_NS.'/releases/'.$r['id']).'?_wpnonce='.wp_create_nonce('wp_rest')).'">Open native readback</a></td></tr>';echo '</tbody></table><h2>Binding an existing native post</h2><p>The destination command <code>native</code> returns the current post fingerprint. Use <code>bind</code> with that fingerprint and its exact original source kind and WordPress ID. This makes subsequent previews target the selected existing post.</p></div>';});});
